17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Map;
28	
29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final AddressNormalizer addressNormalizer;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 AddressNormalizer addressNormalizer) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	        this.addressNormalizer = addressNormalizer;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String address = addressNormalizer.normalize(owner.getAddress());
120	        if (address.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	        }
123	        owner.setAddress(address);
124	        String telephone = toE164(owner.getTelephone());
125	        if (telephone == null) {
126	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
127	        }
128	        owner.setTelephone(telephone);
129	        if (!owner.isPostcodeValid()) {
130	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	        }
132	        if (owner.getRegistrationDate() != null
133	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
134	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
135	        }
136	        LocalDate effectiveDate = owner.getRegistrationDate() != null
137	            ? owner.getRegistrationDate() : LocalDate.now();
138	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
139	        if (isDailyLimitReached(owner.getRegistrationDate())) {
140	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
141	        }
142	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
143	        if (sharesHousehold) {
144	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
145	        }
146	        if (isDuplicate(owner)) {
147	            return new ResponseEntity<>(HttpStatus.CONFLICT);
148	        }
149	        if (isCityAtCapacity(owner.getCity())) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        owner.setCustomerCode(customerCode(owner));
153	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
154	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
155	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
156	        this.clinicService.saveOwner(owner);
157	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
158	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
159	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    /**
166	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
167	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
168	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
169	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
170	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
171	     * every value built from the customer code (the membership number and its check digit) and the
172	     * owner's locality are derived from it.
173	     */
174	    private String customerCode(Owner owner) {
175	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
176	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
177	        return region + "-" + hash8;
178	    }
179	
180	    /**
181	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
182	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
183	     * (business-day) registration date of the owner being created, so owners are counted per
184	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
185	     */
186	    private boolean isDailyLimitReached(LocalDate day) {
187	        long count = this.clinicService.findAllOwners().stream()
188	            .filter(existing -> day.equals(existing.getRegistrationDate()))
189	            .count();
190	        return count >= 100;
191	    }
192	
193	    /**
194	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
195	     * more than 80 owners have already been created for the given business day. Counts the owners
196	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
197	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
198	     * warning.
199	     */
200	    private boolean isBulkSignup(LocalDate day) {
201	        long count = this.clinicService.findAllOwners().stream()
202	            .filter(existing -> day.equals(existing.getRegistrationDate()))
203	            .count();
204	        return count > 80;
205	    }
206	
207	    /**
208	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
209	     * advance it to the following Monday; a weekday is returned unchanged.
210	     */
211	    private LocalDate toBusinessDay(LocalDate date) {
212	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
213	            date = date.plusDays(1);
214	        }
215	        return date;
216	    }
217	
218	    /**
219	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
220	     * more owners. Cities are compared case-insensitively.
221	     */
222	    private boolean isCityAtCapacity(String city) {
223	        long count = this.clinicService.findAllOwners().stream()
224	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
225	            .count();
226	        return count >= 50;
227	    }
228	
229	    /**
230	     * The number of existing owners that already share the given firstName and lastName,
231	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
232	     * whitespace runs collapsed). Counted over the owners present before this create.
233	     */
234	    private int namesakeCount(String firstName, String lastName) {
235	        String candidateFirstName = normalizeName(firstName);
236	        String candidateLastName = normalizeName(lastName);
237	        return (int) this.clinicService.findAllOwners().stream()
238	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
239	                && normalizeName(existing.getLastName()).equals(candidateLastName))
240	            .count();
241	    }
242	
243	    /**
244	     * The number of members in this owner's household after this create: the count of existing
245	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
246	     * created. An owner with no household ({@code householdId == null}) is a household of one.
247	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
248	     * does not depend on the order in which household members were created.
249	     */
250	    private int householdSize(String householdId) {
251	        if (householdId == null) {
252	            return 1;
253	        }
254	        long existing = this.clinicService.findAllOwners().stream()
255	            .filter(other -> householdId.equals(other.getHouseholdId()))
256	            .count();
257	        return (int) existing + 1;
258	    }
259	
260	    /**
261	     * The number of national (subscriber) digits required for each known country calling
262	     * code, keyed by the code's digits (without the leading '+'). A number whose country
263	     * code appears here must carry exactly this many digits after the code, e.g. '+61'
264	     * requires 9 national digits and '+1' requires 10.
265	     */
266	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
267	        "1", 10,
268	        "61", 9);
269	
270	    /**
271	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
272	     * cannot form a valid E.164 number.
273	     *
274	     * <p>A leading '+' and country code are kept when present; otherwise country code
275	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
276	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
277	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
278	     * exactly the national-digit count that code requires (see
279	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}); otherwise it is rejected as invalid.
280	     */
281	    private String toE164(String telephone) {
282	        if (telephone == null) {
283	            return null;
284	        }
285	        boolean hasCountryCode = telephone.trim().startsWith("+");
286	        String digits = telephone.replaceAll("\\D", "");
287	        String e164;
288	        if (hasCountryCode) {
289	            e164 = digits;
290	        } else {
291	            if (digits.startsWith("0")) {
292	                digits = digits.substring(1);
293	            }
294	            e164 = "61" + digits;
295	        }
296	        if (e164.length() < 8 || e164.length() > 15) {
297	            return null;
298	        }
299	        if (!hasValidNationalLength(e164)) {
300	            return null;
301	        }
302	        return "+" + e164;
303	    }
304	
305	    /**
306	     * Whether the E.164 digit string (no leading '+') carries the national-number length
307	     * required by its country calling code. The longest matching known code wins; a number
308	     * whose country code is not recognised passes this check (its length is governed only by
309	     * the general 8-15 digit bound in {@link #toE164}).
310	     */
311	    private boolean hasValidNationalLength(String e164) {
312	        return NATIONAL_DIGITS_BY_COUNTRY.entrySet().stream()
313	            .filter(entry -> e164.startsWith(entry.getKey()))
314	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
315	            .map(entry -> e164.length() - entry.getKey().length() == entry.getValue())
316	            .orElse(true);
317	    }
318	
319	    /**
320	     * Whether the candidate owner duplicates an owner that already exists, and so must be
321	     * rejected with {@code 409 Conflict}. All duplicate detection is consolidated into a single
322	     * derived {@link Owner#getIdentityKey() identityKey} — the normalized telephone, email (or
323	     * empty) and householdId (or empty) joined with {@code '|'} — and an owner is a duplicate only
324	     * when its WHOLE identity key equals that of an existing owner. Because the telephone is part
325	     * of the key, two members of the same household with different telephones have different
326	     * identity keys and are both allowed; only an exact full-key match is a duplicate.
327	     */
328	    private boolean isDuplicate(Owner owner) {
329	        String identityKey = owner.getIdentityKey();
330	        return this.clinicService.findAllOwners().stream()
331	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
332	    }
333	
334	    /**
335	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
336	     * to a single space and lower-case. A null value normalizes to the empty string.
337	     */
338	    private String normalizeName(String value) {
339	        if (value == null) {
340	            return "";
341	        }
342	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
343	    }
344	
345	    /**
346	     * A stable shared identifier for the household formed by a given lastName and address.
347	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
348	     * lastName and address, so every owner sharing the same household is assigned the same
349	     * value regardless of the order in which they are created. Formatted as the first 12
350	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
351	     */
352	    private String householdId(String lastName, String address) {
353	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
354	        return shaHexUpper(key).substring(0, 12);
355	    }
356	
357	    /**
358	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
359	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
360	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
361	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
362	     * {@link #customerCode} keeps the first 8).
363	     */
364	    private String shaHexUpper(String input) {
365	        try {
366	            byte[] digest = MessageDigest.getInstance("SHA-256")
367	                .digest(input.getBytes(StandardCharsets.UTF_8));
368	            StringBuilder sb = new StringBuilder(digest.length * 2);
369	            for (byte b : digest) {
370	                sb.append(String.format("%02x", b));
371	            }
372	            return sb.toString().toUpperCase();
373	        }
374	        catch (NoSuchAlgorithmException e) {
375	            throw new IllegalStateException("SHA-256 not available", e);
376	        }
377	    }
378	
379	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
380	    @Override
381	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
382	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
383	        if (currentOwner == null) {
384	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
385	        }
386	        currentOwner.setAddress(ownerFieldsDto.getAddress());
387	        currentOwner.setCity(ownerFieldsDto.getCity());
388	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
389	        currentOwner.setLastName(ownerFieldsDto.getLastName());
390	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
391	        this.clinicService.saveOwner(currentOwner);
392	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
393	    }
394	
395	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
396	    @Transactional
397	    @Override
398	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
399	        Owner owner = this.clinicService.findOwnerById(ownerId);
400	        if (owner == null) {
401	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
402	        }
403	        this.clinicService.deleteOwner(owner);
404	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
405	    }
406	
407	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
408	    @Override
409	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
410	        Owner owner = this.clinicService.findOwnerById(ownerId);
411	        if (owner == null) {
412	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
413	        }
414	        HttpHeaders headers = new HttpHeaders();
415	        Pet pet = petMapper.toPet(petFieldsDto);
416	        owner.setId(ownerId);
417	        pet.setOwner(owner);
418	        pet.getType().setName(null);
419	        this.clinicService.savePet(pet);
420	        PetDto petDto = petMapper.toPetDto(pet);
421	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
422	            .buildAndExpand(pet.getId()).toUri());
423	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
424	    }
425	
426	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
427	    @Override
428	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
429	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
430	        if (currentOwner != null) {
431	            Pet currentPet = this.clinicService.findPetById(petId);
432	            if (currentPet != null) {
433	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
434	                currentPet.setName(petFieldsDto.getName());
435	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
436	                this.clinicService.savePet(currentPet);
437	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
438	            }
439	        }
440	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
441	    }
442	
443	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
444	    @Override
445	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
446	        HttpHeaders headers = new HttpHeaders();
447	        Visit visit = visitMapper.toVisit(visitFieldsDto);
448	        Pet pet = new Pet();
449	        pet.setId(petId);
450	        visit.setPet(pet);
451	        this.clinicService.saveVisit(visit);
452	        VisitDto visitDto = visitMapper.toVisitDto(visit);
453	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
454	            .buildAndExpand(visit.getId()).toUri());
455	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
456	    }
457	
458	
459	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
460	    @Override
461	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
462	        Owner owner = this.clinicService.findOwnerById(ownerId);
463	        if (owner != null) {
464	            Pet pet = owner.getPet(petId);
465	            if (pet != null) {
466	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
467	            }
468	        }
469	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
470	    }
471	}
