98	    }
99	
100	    public String getPostcode() {
101	        return this.postcode;
102	    }
103	
104	    public void setPostcode(String postcode) {
105	        this.postcode = postcode;
106	    }
107	
108	    public String getTelephone() {
109	        return this.telephone;
110	    }
111	
112	    public void setTelephone(String telephone) {
113	        this.telephone = telephone;
114	    }
115	
116	    public String getEmail() {
117	        return this.email;
118	    }
119	
120	    public void setEmail(String email) {
121	        this.email = email == null ? null : email.toLowerCase();
122	    }
123	
124	    public LocalDate getRegistrationDate() {
125	        return this.registrationDate;
126	    }
127	
128	    public void setRegistrationDate(LocalDate registrationDate) {
129	        this.registrationDate = registrationDate;
130	    }
131	
132	    public LocalDate getBirthDate() {
133	        return this.birthDate;
134	    }
135	
136	    public void setBirthDate(LocalDate birthDate) {
137	        this.birthDate = birthDate;
138	    }
139	
140	    /**
141	     * The owner's age band derived from {@link #birthDate} relative to the
142	     * {@link #registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
143	     * and {@code 'SENIOR'} at 65 or older. Returns {@code null} when no birthDate is set. The age
144	     * is the number of complete years between the birthDate and the registrationDate (or the
145	     * current date when the registrationDate is not yet set).
146	     */
147	    public String getAgeBand() {
148	        if (this.birthDate == null) {
149	            return null;
150	        }
151	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
152	        int years = Period.between(this.birthDate, reference).getYears();
153	        if (years < 18) {
154	            return "MINOR";
155	        }
156	        if (years < 65) {
157	            return "ADULT";
158	        }
159	        return "SENIOR";
160	    }
161	
162	    public String getCustomerCode() {
163	        return this.customerCode;
164	    }
165	
166	    public void setCustomerCode(String customerCode) {
167	        this.customerCode = customerCode;
168	    }
169	
170	    public String getHouseholdId() {
171	        return this.householdId;
172	    }
173	
174	    public void setHouseholdId(String householdId) {
175	        this.householdId = householdId;
176	    }
177	
178	    public Integer getNamesakeCount() {
179	        return this.namesakeCount;
180	    }
181	
182	    public void setNamesakeCount(Integer namesakeCount) {
183	        this.namesakeCount = namesakeCount;
184	    }
185	
186	    public Boolean getBulkSignupWarning() {
187	        return this.bulkSignupWarning;
188	    }
189	
190	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
191	        this.bulkSignupWarning = bulkSignupWarning;
192	    }
193	
194	    public Integer getHouseholdSize() {
195	        return this.householdSize;
196	    }
197	
198	    public void setHouseholdSize(Integer householdSize) {
199	        this.householdSize = householdSize;
200	    }
201	
202	    /**
203	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
204	     */
205	    public String getDisplayName() {
206	        return this.getLastName() + ", " + this.getFirstName();
207	    }
208	
209	    /**
210	     * The owner's initials: the upper-cased first letters of firstName and lastName,
211	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
212	     */
213	    public String getInitials() {
214	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
215	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
216	    }
217	
218	    /**
219	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
220	     * last two digits of the registrationDate year, e.g. {@code 'NSW-3C1A9F2B-M26'}.
221	     */
222	    public String getMembershipNumber() {
223	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
224	    }
225	
226	    /**
227	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
228	     * contained in the owner's {@link #customerCode}.
229	     */
230	    public int getCheckDigit() {
231	        return luhnCheckDigit(this.customerCode);
232	    }
233	
234	    /**
235	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
236	     * contained in {@code value}. Reading the digits right to left, every second one is
237	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
238	     * digits are summed, and the check digit is the amount that must be added to that sum to
239	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
240	     * the digit is taken over exactly the digits the string carries.
241	     */
242	    private static int luhnCheckDigit(String value) {
243	        int sum = 0;
244	        boolean doubling = true;
245	        for (int i = value.length() - 1; i >= 0; i--) {
246	            char c = value.charAt(i);
247	            if (c < '0' || c > '9') {
248	                continue;
249	            }
250	            int digit = c - '0';
251	            if (doubling) {
252	                digit *= 2;
253	                if (digit > 9) {
254	                    digit -= 9;
255	                }
256	            }
257	            sum += digit;
258	            doubling = !doubling;
259	        }
260	        return (10 - (sum % 10)) % 10;
261	    }
262	
263	    /** Fixed city-to-region table used to derive an owner's locality. */
264	    private static final Map<String, String> CITY_REGION = Map.of(
265	        "Sydney", "NSW",
266	        "Melbourne", "VIC",
267	        "Brisbane", "QLD");
268	
269	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
270	    public static final String UNKNOWN_REGION = "UNKNOWN";
271	
272	    /**
273	     * The canonical region for a city, derived from the fixed city-to-region table
274	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
275	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
276	     * source of the city-to-region mapping, shared by every rule that is keyed by
277	     * region so the mapping is never re-derived elsewhere.
278	     */
279	    public static String regionOf(String city) {
280	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
281	    }
282	
283	    /**
284	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
285	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
286	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
287	     * known region). Locality is read from the region-and-hash identity so it never re-derives
288	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
289	     */
290	    public String getLocality() {
291	        if (this.customerCode == null) {
292	            return UNKNOWN_REGION;
293	        }
294	        int dash = this.customerCode.indexOf('-');
295	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
296	    }
297	
298	    /**
299	     * The region derived from this owner's postcode alone: the region whose fixed
300	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
301	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
302	     * component built into the owner's customer code at creation and, through it, the source of the
303	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
304	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
305	     */
306	    public String getRegion() {
307	        return regionOfPostcode(this.postcode);
308	    }
309	
310	    /**
311	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
312	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
313	     * no known range.
314	     */
315	    private static String regionOfPostcode(String postcode) {
316	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
317	            return null;
318	        }
319	        int value = Integer.parseInt(postcode);
320	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
321	            int[] range = entry.getValue();
322	            if (value >= range[0] && value <= range[1]) {
323	                return entry.getKey();
324	            }
325	        }
326	        return null;
327	    }
328	
329	    /**
330	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
331	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
332	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
333	     */
334	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
335	        "NSW", new int[] {2000, 2099},
336	        "VIC", new int[] {3000, 3099},
337	        "QLD", new int[] {4000, 4099});
338	
339	    /**
340	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
341	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
342	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
343	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
344	     * city with no known region accepts any 4-digit postcode.
345	     */
346	    public boolean isPostcodeValid() {
347	        if (this.postcode == null) {
348	            return true;
349	        }
350	        if (!this.postcode.matches("[0-9]{4}")) {
351	            return false;
352	        }
353	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
354	        if (range == null) {
355	            return true;
356	        }
357	        int value = Integer.parseInt(this.postcode);
358	        return value >= range[0] && value <= range[1];
359	    }
360	
361	    /**
362	     * The owner's membership level, a number from 1 to 3 determined on creation: it starts at 1,
363	     * gains 1 when an email is present, gains 1 when namesakeCount is 0, and is capped at 3.
364	     * Level 4 is reserved for tenure.
365	     */
366	    public Integer getMembershipLevel() {
367	        int level = 1;
368	        if (this.email != null && !this.email.isEmpty()) {
369	            level++;
370	        }
371	        if (this.namesakeCount != null && this.namesakeCount == 0) {
372	            level++;
373	        }
374	        return Math.min(level, 3);
375	    }
376	
377	    /**
378	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
379	     * otherwise {@code 'PHONE'}.
380	     */
381	    public String getContactPreference() {
382	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
383	    }
384	
385	    /**
386	     * The owner's identity key: the single derived value used for duplicate detection.
387	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
388	     * empty string when absent) and the householdId (or the empty string when the owner
389	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
390	     * Two owners are duplicates only when their whole identity keys are equal.
391	     */
392	    public String getIdentityKey() {
393	        String telephonePart = this.telephone == null ? "" : this.telephone;
394	        String emailPart = this.email == null ? "" : this.email;
395	        String householdPart = this.householdId == null ? "" : this.householdId;
396	        return telephonePart + "|" + emailPart + "|" + householdPart;
397	    }
398	
399	    protected Set<Pet> getPetsInternal() {
400	        if (this.pets == null) {
401	            this.pets = new HashSet<>();
402	        }
403	        return this.pets;
404	    }
405	
406	    protected void setPetsInternal(Set<Pet> pets) {
407	        this.pets = pets;
408	    }
409	
410	    public List<Pet> getPets() {
411	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
412	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
413	        return Collections.unmodifiableList(sortedPets);
414	    }
415	
416	    public void setPets(List<Pet> pets) {
417	        this.pets = new HashSet<>(pets);
418	    }
419	
420	    public void addPet(Pet pet) {
421	        getPetsInternal().add(pet);
422	        pet.setOwner(this);
423	    }
424	
425	    /**
426	     * Return the Pet with the given name, or null if none found for this Owner.
427	     *
428	     * @param name to test
429	     * @return true if pet name is already in use
430	     */
431	    public Pet getPet(String name) {
432	        return getPet(name, false);
433	    }
434	
435	    /**
436	     * Return the Pet with the given name, or null if none found for this Owner.
437	     *
438	     * @param name to test
439	     * @return true if pet name is already in use
440	     */
441	    public Pet getPet(String name, boolean ignoreNew) {
442	        name = name.toLowerCase();
443	        for (Pet pet : getPetsInternal()) {
444	            if (!ignoreNew || !pet.isNew()) {
445	                String compName = pet.getName();
446	                compName = compName.toLowerCase();
447	                if (compName.equals(name)) {
448	                    return pet;
449	                }
450	            }
451	        }
452	        return null;
453	    }
454	
455	    public Pet getPet(Integer petId) {
456	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
457	    }
458	
459	    @Override
